function jobSnapshot(w,j){const mooring=get(w,'moorings',j.mooringId);return {job:normalize(w,'jobs',j),mooring,owner:mooring.ownerId?get(w,'people',mooring.ownerId):null,components:w.components.filter(c=>c.mooringId===mooring.id),permit:j.permitId?get(w,'permits',j.permitId):null,crew:j.crewIds.map(x=>get(w,'people',x)),resources:j.resourceIds.map(x=>get(w,'resources',x))};}
